  {"id": 36, "name": "Joe Buttataki", "role": "DWMA Investigator", "species": "Human", "affiliation": "DWMA", "weapon_partner": "Marie Mjolnir (formerly)", "abilities": ["Super-Sensor Perception (Soul Detection)", "Advanced Forensic Investigation"], "description": "A specialized investigator brought into Death City to uncover a hidden traitor within the academy. Known as 'Joe the Tracker,' he possesses an extraordinarily acute sensory skill that lets him perceive minute distortions in individuals' souls. He shares a romantic history with Marie Mjolnir.", "status": "Deceased", "first_appearance": {"anime": "Episode 37", "manga": "Chapter 38"}, "voice_actor": {"japanese": "子安武人 (Takehito Koyasu)", "english": "Jason Douglas"}},
