  {"id": 75, "name": "Vajra", "role": "Former Weapon Partner", "species": "Demon Weapon", "affiliation": "Independent (formerly Lord Death's Legion)", "weapon_partner": "Asura (formerly)", "abilities": ["Unknown/Not extensively detailed in canon"], "description": "Asura's original weapon partner before Asura's descent into madness. Asura's paranoia and fear ultimately drove him to swallow Vajra alive rather than continue as his meister, an act that set off the chain of events leading to Asura becoming the first Kishin.", "status": "Deceased (Consumed by Asura)", "first_appearance": {"anime": "Referenced only", "manga": "Referenced in backstory"}, "voice_actor": {"japanese": "Not documented", "english": "Not documented"}},
