  {"id": 77, "name": "Pot of Thunder", "role": "Demon Weapon", "species": "Demon Weapon", "affiliation": "DWMA / Spartoi", "weapon_partner": "Kilik Rung (shared with Pot of Fire)", "abilities": ["Gauntlet Transformation (Lightning Element)", "Electricity Generation", "Soul Resonance"], "description": "The other of Kilik Rung's twin weapon partners, transforming into his lightning-based gauntlet. Alongside her sister Pot of Fire, she completes Kilik's signature dual-gauntlet combat style.", "status": "Alive", "first_appearance": {"anime": "Episode 21", "manga": "Chapter 18"}, "voice_actor": {"japanese": "Not widely documented", "english": "Not widely documented"}},
  {"id": 78, "name": "Enrique", "role": "Meister / Death Scythe Partner", "species": "Monkey", "affiliation": "DWMA (South American Branch)", "weapon_partner": "Tezca Tlipoca", "abilities": ["Cannot be understood by most humans (communicates only with Tezca)"], "description": "An ordinary monkey who serves as meister to the Death Scythe Tezca Tlipoca, in charge of DWMA's South American branch. Only Tezca can understand what he says.", "status": "Alive"},
  {"id": 79, "name": "Feodor", "role": "Meister / Death Scythe Partner", "species": "Human", "affiliation": "DWMA (Russian/Eastern European Branch)", "weapon_partner": "Tsar Pushka", "abilities": ["Cossack-style Fighting", "Close-Quarters Kicks"], "description": "Meister to the Death Scythe Tsar Pushka, in charge of Russia/Eastern Europe. Stationed in Ukraine, he and Tsar were killed in battle against Crona.", "status": "Deceased"},
  {"id": 80, "name": "Alexandre", "role": "Meister / Death Scythe Partner", "species": "Human", "affiliation": "DWMA (African Branch)", "weapon_partner": "Dengu Dinga", "abilities": ["Not extensively documented"], "description": "Meister to the Death Scythe Dengu Dinga, in charge of DWMA's African branch. Arrives at DWMA shortly before the final battle against Asura.", "status": "Unconfirmed"},
