abilities = [    
  {"id": 1, "name": "Soul Perception", "ability_type": "Sensory / Passive", "users": ["Maka Albarn", "Franken Stein", "Asura", "Tezca Tlipoca"], "description": "The rare capability to visually perceive the souls of living beings, monsters, and weapons. Advanced practitioners can gauge a target's power levels, emotional state, alignment, and track their position across massive distances by reading their spiritual wavelength signature."},
  {"id": 2, "name": "Anti-Demon Wavelength", "ability_type": "Offensive / Defensive / Spiritual", "users": ["Maka Albarn", "Spirit Albarn", "Tsar Pushka"], "description": "An exceptionally pure form of soul wavelength that acts as a natural counter to corruption, immorality, and madness. It can pierce through protective barriers, neutralize regeneration or immortality traits, and restore stability to minds heavily infected by madness."},
  {"id": 3, "name": "Soul Menace (Wavelength Strike)", "ability_type": "Offensive Martial Arts", "users": ["Franken Stein", "Black Star"], "description": "A combat technique where the user channels their raw soul wavelength directly through their bare hands or limbs, releasing it as a concentrated kinetic shockwave upon striking the target. It bypasses external physical armor to damage internal organs and disrupt the victim's spiritual flow."},
  {"id": 4, "name": "Black Blood Manipulation", "ability_type": "Defensive / Offensive / Symbiotic", "users": ["Crona", "Ragnarok", "Soul Eater Evans", "Maka Albarn"], "description": "The weaponization of a synthesized, madness-infused blood strain. It allows the user to instantly harden their blood to form near-impenetrable armor, forge external blades from open wounds, or trigger intense psychological mania to augment overall combat threshold."},
  {"id": 5, "name": "Sanzu Lines Awakening", "ability_type": "God / Passive Amplification", "users": ["Death the Kid"], "description": "The gradual connection of the three halo-like rings running across the hair of a Grim Reaper. As these lines align and ignite, the user unlocks their latent godhood, massively scaling their baseline power, structural resilience, and spiritual output to maximum tiers."},
  {"id": 6, "name": "Maji Hunt (Genie Hunter)", "ability_type": "Ultimate Resonance (Scythe)", "users": ["Maka Albarn", "Soul Eater Evans", "Spirit Albarn"], "description": "An advanced Soul Resonance execution that transforms a demon scythe blade into a giant, sweeping broad-blade format glowing with holy energy, specialized in clean-cutting high-tier demons, witches, and manifestation entities."},
  {"id": 7, "name": "Kishin Hunt (Maestro Hunter)", "ability_type": "God-Tier Resonance (Scythe)", "users": ["Maka Albarn", "Soul Eater Evans"], "description": "The absolute pinnacle development of the Scythe Meister resonance techniques. The weapon morphs into a massive blade of concentrated, blinding anti-demon light designed to tear through structural god-level threats and concepts of total madness."},
  {"id": 8, "name": "Enchanted Sword Mode", "ability_type": "Form Shifting / Shadow Control", "users": ["Tsubaki Nakatsukasa", "Black Star"], "description": "A high-risk combat form inherited after defeating the corrupted spirit Masamune. Tsubaki converts into a sleek, dark ninja sword that grants her meister the ability to manipulate corporeal shadows, bind enemy movements, or execute clone arrays."},
  {"id": 9, "name": "Shadow Star Style (Kageboshi)", "ability_type": "Assassination / Shadow Manipulation", "users": ["Black Star"], "description": "An elite combat art utilizing the Enchanted Sword form. The meister manipulates their own shadow to form solid constructs, extra appendages, or traps, allowing for unconventional misdirection and multi-directional martial combos."},
  {"id": 10, "name": "Death Cannon", "ability_type": "Heavy Range Resonance", "users": ["Death the Kid", "Liz Thompson", "Patty Thompson"], "description": "A Soul Resonance technique where the dual Thompson pistols transform into two heavy, arm-mounted mechanical cannons. Charging spiritual energy to 100% output allows the user to unleash massive, dual-trajectory destructive plasma blasts."},
  {"id": 11, "name": "Screaming Resonance (Screech Alpha)", "ability_type": "Acoustic Offense", "users": ["Crona", "Ragnarok"], "description": "An offensive resonance execution where the Demon Sword Ragnarok opens a mouth on its blade and emits a high-decibel, localized acoustic scream. The sonic waves distort tracking, shatter defenses, and drive nearby enemies toward panic."},
  {"id": 12, "name": "Izuna (Lightning Generation)", "ability_type": "Elemental Martial Arts", "users": ["Marie Mjolnir", "Franken Stein"], "description": "A specialized technique that channels electricity through a hammer or tonfa weapon form. It alters the meister's nervous system to dramatically boost reflexes and motor speed while wrapping their physical attacks in high-voltage arcs."},
  {"id": 13, "name": "Senrigan (Clairvoyant Mapping)", "ability_type": "Tactical / Sensory", "users": ["Azusa Yumi"], "description": "An advanced tracking capability linked to a sniper or crossbow form. The user can map topographical grids across several kilometers, processing real-time positions, wind speed, and data metrics to transmit layout details straight to allies' brains."},
  {"id": 14, "name": "Solar Beam Reflection", "ability_type": "Optical / Ranged Offense", "users": ["Tezca Tlipoca", "Enrique"], "description": "A light-focusing offensive technique deployed via a mirror weapon form. It gathers ambient solar rays or spiritual energy and concentrates them into a pinpoint, searing laser beam capable of melting dense defenses instantly."},
  {"id": 15, "name": "Phantom Illusion Projection", "ability_type": "Deception / Spatial Magic", "users": ["Tezca Tlipoca"], "description": "The ability to manipulate spatial light fields to project highly convincing, interactive visual decoys of oneself or others, effectively masking actual tactical positions and drawing enemy fire away from real assets."},
  {"id": 16, "name": "Pyrokinesis Manifestation", "ability_type": "Elemental Offense", "users": ["Pot of Fire", "Kilik Rung", "Jacqueline O'Lantern Dupré", "Kim Diehl"], "description": "The tactical projection and manipulation of intense flames. Users can wrap their physical strikes in explosive combustion heat or channel fire streams into propulsion systems to navigate open airspaces rapidly."},
  {"id": 17, "name": "Electrokinesis Manifestation", "ability_type": "Elemental Offense / Paralysis", "users": ["Pot of Thunder", "Kilik Rung", "Harvar D. Éclair", "Ox Ford"], "description": "The generation of high-voltage electrical fields through piercing or blunt-force melee strikes. It inflicts acute electrical burns upon contact and disrupts the target's neural or muscular systems to cause instant paralysis."},
  {"id": 18, "name": "Madness Wavelength Emission", "ability_type": "Mental Corruption / Passive AoE", "users": ["Asura", "Arachne Gorgon", "Justin Law"], "description": "The continuous, passive radiation of psychological madness that warps the minds of anyone inside its expansive field. It amplifies baseline fears, paranoia, and violent impulses, forcing victims to succumb to hallucinations or total mental collapse."}
]

arcs = [
  {"id": 1, "name": "Introduction Arc / Prologue", "episodes": "1-3", "manga_chapters": "Prologue 1-3", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson"], "main_conflict": "Collecting 99 evil human souls and 1 witch soul to forge a Death Scythe.", "description": "Introduces the main cast of meisters and weapons as they undergo standalone tests to harvest corrupted souls. Each pair struggles with their unique character flaws—perfectionism, arrogance, and academic anxiety—before failing their final witch soul collection trial, resetting their counts.", "status": "Completed"},
  {"id": 2, "name": "Remedial Lessons Arc", "episodes": "4-7", "manga_chapters": "1-5", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Franken Stein", "Sid Barett"], "main_conflict": "Investigating a rogue undead staff member threatening students to secure remedial credits.", "description": "Following their soul-harvesting failures, Maka and Black Star's teams are sent on a joint remedial assignment by Lord Death. They track down their resurrected, zombified teacher Sid, leading them straight to the eccentric, powerful mad scientist Dr. Franken Stein for an intensive trial by combat.", "status": "Completed"},
  {"id": 3, "name": "The Dark Arm Arc (Enchanted Sword Arc)", "episodes": "10-11", "manga_chapters": "6-8", "main_characters": ["Black Star", "Tsubaki Nakatsukasa", "Mifune", "Angela Leon", "Masamune Nakatsukasa"], "main_conflict": "Defeating a corrupted multi-form weapon and protecting a young witch.", "description": "Black Star and Tsubaki travel to an isolated village to stop the Enchanted Sword, Masamune, who has surrendered to bloodlust. Tsubaki faces her brother inside her spiritual domain while Black Star clashes with the master samurai bodyguard Mifune over the fate of the child witch Angela.", "status": "Completed"},
  {"id": 4, "name": "Black Blood Arc (Italy / Immortal Clan)", "episodes": "12-14", "manga_chapters": "9-15", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Crona", "Ragnarok", "Medusa Gorgon", "Free"], "main_conflict": "Surviving the lethal introduction of Black Blood and neutralizing an escaped immortal criminal.", "description": "During an extracurricular trip to Florence, Italy, Maka encounters Crona, a deeply unstable meister wielding a screeching demon sword fueled by synthetic Black Blood. Soul is critically wounded protecting Maka, infecting him with madness. Later, the DWMA mobilizes to contain Free, an immortal werewolf freed by Medusa.", "status": "Completed", "image_url": "/arcs/arcs-black-blood.png"},
  {"id": 5, "name": "Kishin Revival Arc (DWMA Anniversary)", "episodes": "15-24", "manga_chapters": "16-22", "main_characters": ["Lord Death", "Franken Stein", "Asura", "Medusa Gorgon", "Maka Albarn", "Soul Eater Evans", "Black Star", "Death the Kid"], "main_conflict": "Infiltrating the DWMA underground vaults to prevent the injection of Black Blood into the sealed Kishin.", "description": "Medusa executes a massive, coordinated surprise attack on the DWMA during its founding celebration. Trapping the senior staff inside an independent pocket dimension, her agents sprint down to the lowest depths beneath the academy to resurrect the original God of Madness, Asura, using an injection of concentrated Black Blood.", "status": "Completed"},
  {"id": 6, "name": "Arachnophobia Arc", "episodes": "25-38", "manga_chapters": "23-44", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Arachne Gorgon", "Giriko", "Mosquito", "Franken Stein", "Crona"], "main_conflict": "A global faction war breaks out as a newly awakened witch organization exploits spreading madness.", "description": "Following Asura's escape, the world is saturated with a madness wavelength that wakes the Heretic Witch Arachne from her 800-year slumber. Her massive spider network, Arachnophobia, enters a hot war against the DWMA for regional control, while Dr. Stein struggles heavily to keep his sanity from fracturing under the localized madness.", "status": "Completed", "image_url": "/arcs/arcs-arachnophobia.png"},
  {"id": 7, "name": "Brew / Baba Yaga's Castle Infiltration Arc", "episodes": "39-51 (Anime Alternate Ending)", "manga_chapters": "45-60", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Death the Kid", "Arachne Gorgon", "Medusa Gorgon", "Asura"], "main_conflict": "Securing Eibon's lost artifact and destroying Arachnophobia's mobile stronghold.", "description": "The DWMA and Arachnophobia clash in the frozen north over 'Brew,' an ultimate magical artifact crafted by Eibon. The conflict escalates into a full-scale siege on Baba Yaga's Castle. In the manga, the cast transitions into the elite squad 'Spartoi' after this raid; in the anime, this arc culminates in a completely original anime-exclusive finale defeating Asura.", "status": "Completed"},
  {"id": 8, "name": "Book of Eibon / Salvage Arc", "episodes": "N/A (Manga Exclusive)", "manga_chapters": "61-81", "main_characters": ["Death the Kid", "Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Noah", "Gopher"], "main_conflict": "Rescuing a kidnapped Grim Reaper prince from the seven sin layers of a magical catalog text.", "description": "Death the Kid is captured by Noah, an antagonist manifestation holed up inside the Book of Eibon. The remaining members of Spartoi launch a deep infiltration rescue mission through the text, braving seven distinct visual dimensions based on the deadly sins that warp their internal traits, genders, and attributes.", "status": "Completed"},
  {"id": 9, "name": "The Moon / Final Battle Arc", "episodes": "N/A (Manga Exclusive)", "manga_chapters": "82-113", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Death the Kid", "Crona", "Asura", "Lord Death"], "main_conflict": "Storming the lunar surface to seal the Kishin permanently and finalize a peace treaty with the Witches.", "description": "The absolute climax of the manga. The DWMA traces Asura's location to the surface of the moon, executing a massive atmospheric deployment. To secure safe passage, Death the Kid forms a historic truce with the Witch Coven. Down on the lunar battlefield, the main trio achieves full tactical awakening to battle Crona and Asura, ending in a permanent seal and Kid ascending as the new Lord Death.", "status": "Completed"}
]